export const version = 4;

function sid(key: string): string {
  const h = sha256('listing:' + key);
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-b${h.slice(17, 20)}-${h.slice(20, 32)}`;
}
const userId = (email: string): string => {
  const r = q.get<{ id: string }>('SELECT id FROM users WHERE email = ?', [email.toLowerCase()]);
  if (!r) throw new Error(`seed/listings: missing core user ${email} — run the core seed first`);
  return r.id;
};

