const SPECS: Spec[] = [...NU, ...UIUC, ...NYU, ...OTHER];

// ------------------------------------------------------------------ bilingual descriptions
const FURN = { none: ['不带家具', 'unfurnished'], partial: ['部分家具（床、桌椅）', 'partly furnished (bed, desk, chairs)'], full: ['家具齐全，拎包入住', 'fully furnished, move-in ready'] } as const;
const LEASE = { sublease: ['转租', 'sublet'], takeover: ['租约接手', 'lease takeover'], new_lease: ['新租约', 'new lease'], month_to_month: ['月付', 'month-to-month'] } as const;
function describe(s: Spec): string {
  const rooms = s.bed === 0 ? 'Studio' : `${s.bed} 室 ${s.bath} 卫`;
  const roomsEn = s.bed === 0 ? 'studio' : `${s.bed} bd · ${s.bath} ba`;
  const zh = [
    s.hookZh,
    `${s.hood} ${s.prop === 'room' || s.prop === 'shared_room' ? '单间' : rooms}，${FURN[s.furn ?? 'none'][0]}，${LEASE[s.lease ?? 'sublease'][0]}。`,
    `${s.from.replace(/-/g, '/')} 起${s.to ? `至 ${s.to.replace(/-/g, '/')}` : '，长期'}${s.flexible ? '，日期可商量' : ''}，最短 ${s.term ?? 1} 个月。`,
    s.utilities ? '租金已含水电网。' : s.utilitiesEst ? `水电网另算，每月约 $${Math.round(s.utilitiesEst / 100)}。` : '水电网按实际分摊。',
    s.roommates ? `现有 ${s.roommates} 位室友${s.gender === 'female' ? '，仅限女生' : s.gender === 'male' ? '，仅限男生' : ''}。` : '',
    s.pets ? '可以养宠物。' : '',
    s.parking && s.parking !== 'none' ? `有${s.parking === 'garage' ? '车库' : s.parking === 'lot' ? '停车场' : '路边'}车位。` : '',
    '看房可以视频也可以线下，私信我约时间。',
  ].filter(Boolean).join('');
  const en = [
    s.hookEn,
    `${s.prop === 'room' || s.prop === 'shared_room' ? 'Private room' : roomsEn.charAt(0).toUpperCase() + roomsEn.slice(1)} in ${s.hood}, ${FURN[s.furn ?? 'none'][1]}, ${LEASE[s.lease ?? 'sublease'][1]}.`,
    `Available ${s.from}${s.to ? ` to ${s.to}` : ' onward'}${s.flexible ? ' (dates flexible)' : ''}, minimum ${s.term ?? 1} month${(s.term ?? 1) > 1 ? 's' : ''}.`,
    s.utilities ? 'Utilities and internet included.' : s.utilitiesEst ? `Utilities are extra, roughly $${Math.round(s.utilitiesEst / 100)}/mo.` : 'Utilities split at cost.',
    s.roommates ? `${s.roommates} current roommate${s.roommates > 1 ? 's' : ''}${s.gender === 'female' ? ', women only' : s.gender === 'male' ? ', men only' : ''}.` : '',
    s.pets ? 'Pets allowed.' : '',
    s.parking && s.parking !== 'none' ? `${s.parking === 'garage' ? 'Garage' : s.parking === 'lot' ? 'Lot' : 'Street'} parking.` : '',
    'Video or in-person tours — message me to set a time.',
  ].filter(Boolean).join(' ');
  return `${zh}\n\n${en}`;
}

// ------------------------------------------------------------------ seed
export default async function seed(_db: DatabaseSync): Promise<void> {
  const now = nowMs();
  const roomUploads: string[] = [];
  for (let i = 1; i <= 60; i++) roomUploads.push(insertSeedUpload({ path: `seed/rooms/r${String(i).padStart(2, '0')}.svg`, purpose: 'seed' }));

  const listingIds = SPECS.map((_, i) => sid(`l${i + 1}`));

  q.tx(() => {
    // wipe previous run (module tables cascade from listings; boosts/events for these ids are ours)
    const ph = listingIds.map(() => '?').join(', ');
    q.run(`DELETE FROM boosts WHERE entity_type = 'listing' AND entity_id IN (${ph})`, listingIds);
    q.run(`DELETE FROM events WHERE entity_type = 'listing' AND entity_id IN (${ph}) AND session_id = 'seed'`, listingIds);
    q.run(`DELETE FROM listings WHERE id IN (${ph})`, listingIds);

    SPECS.forEach((s, i) => {
      const id = listingIds[i]!;
      const ownerId = userId(s.owner);
      const owner = q.get<{ trust_level: number }>('SELECT trust_level FROM users WHERE id = ?', [ownerId])!;
      const status = s.status ?? 'active';
      const publishedAt = status === 'draft' ? null : new Date(now - s.publishedDaysAgo * DAY - (i % 7) * 3_600_000).toISOString();
      const createdAt = new Date(now - (s.publishedDaysAgo + 1) * DAY - (i % 5) * 3_600_000).toISOString();
      const fromMs = new Date(s.from + 'T00:00:00Z').getTime();
      let expiresAt: string | null = null;
      if (status === 'active' || status === 'paused') expiresAt = new Date(Math.max(fromMs, now) + 45 * DAY).toISOString();
      if (status === 'expired') expiresAt = new Date(now - 2 * DAY).toISOString();
      if (status === 'rented') expiresAt = new Date(fromMs + 45 * DAY).toISOString();
      const campus = getCampus(s.campus)!;
      const distance = haversineM({ lat: s.lat, lng: s.lng }, { lat: campus.lat, lng: campus.lng });
      const ns = nearestStop(s.campus, s.lat, s.lng, 3000);
      // nearest_stop_m is a listings-owned cache; when the shuttle seed has not run yet, keep plausible values for Evanston
      // addresses that sit on the Northwestern intercampus / Evanston loop (so the near-shuttle chip is visible in demos).
      const evanstonNear = s.campus === 'northwestern' && s.city === 'Evanston' && ['North Evanston', 'Downtown Evanston'].includes(s.hood) && i % 3 !== 1;
      const stopM = ns ? ns.distanceM : evanstonNear ? 120 + (i * 37) % 260 : null;
      const stopToCampus = ns ? haversineM({ lat: ns.stop.lat, lng: ns.stop.lng }, { lat: campus.lat, lng: campus.lng }) : evanstonNear ? Math.max(400, distance - 300) : null;
      const shuttleMin = stopM !== null && stopM <= 1200 && stopToCampus !== null ? Math.ceil(stopM / 80) + Math.ceil((stopToCampus / 1000) * 3) : null;
      const photoCount = Math.max(2, Math.min(8, s.photos));
      const coverIdx = (i * 7) % 60;
      q.run(
        `INSERT INTO listings (id, owner_id, campus_id, title, description, listing_type, property_type, address_line1, address_line2, city, state, zip, country, lat, lng,
           geocode_precision, hide_exact_address, neighborhood, price_cents, deposit_cents, utilities_included, utilities_note, utilities_est_cents, bedrooms, bathrooms, sqft,
           furnished, available_from, available_to, min_term_months, flexible_dates, lease_type, roommates_count, gender_pref, pets_allowed, parking, smoking_allowed,
           status, moderation_status, is_verified_listing, published_at, expires_at, rented_at, cover_upload_id, view_count,
           distance_to_campus_m, commute_walk_min, commute_bike_min, commute_shuttle_min, nearest_stop_id, nearest_stop_m, created_at, updated_at)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'US', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'ok', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
          id, ownerId, s.campus, s.title, describe(s), s.type ?? 'sublet', s.prop ?? 'apartment', s.addr, null, s.city, s.state, s.zip, s.lat, s.lng,
          s.precision ?? 'rooftop', s.hide === false ? 0 : 1, s.hood, s.price, s.deposit ?? s.price, s.utilities ? 1 : 0, s.utilitiesNote ?? null, s.utilitiesEst ?? (s.utilities ? null : 9000 + (i % 5) * 1500),
          s.bed, s.bath, s.sqft ?? null, s.furn ?? 'none', s.from, s.to ?? null, s.term ?? 1, s.flexible ? 1 : 0, s.lease ?? 'sublease', s.roommates ?? 0, s.gender ?? 'any',
          s.pets ? 1 : 0, s.parking ?? 'none', s.smoking ? 1 : 0, status, status === 'draft' ? 0 : owner.trust_level >= 2 ? 1 : 0, publishedAt, expiresAt,
          status === 'rented' ? new Date(now - 5 * DAY).toISOString() : null, roomUploads[coverIdx]!, s.views,
          distance, Math.ceil(distance / 80), Math.ceil(distance / 250), shuttleMin, ns?.stop.id ?? null, stopM, createdAt, publishedAt ?? createdAt,
        ],
      );
      for (let p = 0; p < photoCount; p++) {
        q.run('INSERT INTO listing_photos (id, listing_id, upload_id, sort_order, caption, created_at) VALUES (?, ?, ?, ?, ?, ?)', [sid(`l${i + 1}:p${p}`), id, roomUploads[(coverIdx + p * 11) % 60]!, p, null, createdAt]);
      }
      for (const a of new Set(s.amen)) q.run('INSERT INTO listing_amenities (listing_id, amenity) VALUES (?, ?)', [id, a]);
      for (const b of s.booked ?? []) q.run('INSERT INTO listing_availability (id, listing_id, start_date, end_date, status, note, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)', [sid(`l${i + 1}:a${b.start}`), id, b.start, b.end, b.status, b.note ?? null, createdAt]);
      if (s.boost && status === 'active') {
        const boostId = sid(`l${i + 1}:boost`);
        const starts = new Date(now - 2 * DAY).toISOString();
        const ends = new Date(now + (s.boost === 'max' ? 14 : s.boost === 'plus' ? 7 : 3) * DAY).toISOString();
        q.run(
          `INSERT INTO boosts (id, user_id, campus_id, entity_type, entity_id, plan_id, order_id, tier, starts_at, ends_at, status, impressions, clicks, created_at, updated_at)
           VALUES (?, ?, ?, 'listing', ?, NULL, NULL, ?, ?, ?, 'active', ?, ?, ?, ?)`,
          [boostId, ownerId, s.campus, id, s.boost, starts, ends, 40 + (i * 13) % 120, 3 + (i % 9), starts, starts],
        );
      }
    });

    // saves + leads (listing_saves / listing_leads are listings-owned; counters come from triggers)
    const saves: [string, number[]][] = [
      ['alice@u.northwestern.edu', [3, 6, 7, 9, 13, 19, 34]],
      ['bob@u.northwestern.edu', [1, 6, 10, 26]],
      ['newbie@u.northwestern.edu', [1, 4, 22, 23]],
      ['tianyi.zhao@u.northwestern.edu', [1, 3, 18, 25]],
      ['yiran.feng@u.northwestern.edu', [4, 14, 22]],
      ['grace.hu@u.northwestern.edu', [1, 7, 13]],
      ['ethan.luo@u.northwestern.edu', [25, 26]],
      ['ryan.zhu@illinois.edu', [46, 47, 48]],
      ['mia.cheng@nyu.edu', [58, 61, 63]],
      ['lanxin.zhang@umich.edu', [71, 73]],
    ];
    for (const [email, idx] of saves) {
      const uid = userId(email);
      for (const n of idx) {
        const lid = listingIds[n - 1];
        if (lid) q.run('INSERT OR IGNORE INTO listing_saves (user_id, listing_id, created_at) VALUES (?, ?, ?)', [uid, lid, new Date(now - (n % 9) * DAY - 3_600_000).toISOString()]);
      }
    }
    const leads: [string, number, string][] = [
      ['bob@u.northwestern.edu', 1, 'replied'], ['tianyi.zhao@u.northwestern.edu', 1, 'new'], ['grace.hu@u.northwestern.edu', 1, 'qualified'], ['yiran.feng@u.northwestern.edu', 1, 'new'],
      ['newbie@u.northwestern.edu', 3, 'new'], ['haoran.zhang@u.northwestern.edu', 3, 'replied'], ['daniel.kim@u.northwestern.edu', 6, 'new'], ['kai.tanaka@u.northwestern.edu', 9, 'replied'],
      ['sophia.wang@u.northwestern.edu', 9, 'new'], ['leo.ma@u.northwestern.edu', 13, 'new'], ['ryan.zhu@illinois.edu', 46, 'new'], ['hana.sato@illinois.edu', 47, 'replied'],
      ['mia.cheng@nyu.edu', 58, 'new'], ['lucia.fernandez@nyu.edu', 59, 'qualified'], ['lanxin.zhang@umich.edu', 71, 'new'], ['bob@u.northwestern.edu', 6, 'closed'],
    ];
    leads.forEach(([email, n, status], k) => {
      const lid = listingIds[n - 1];
      if (!lid) return;
      const ownerId = q.get<{ owner_id: string }>('SELECT owner_id FROM listings WHERE id = ?', [lid])!.owner_id;
      q.run('INSERT OR IGNORE INTO listing_leads (id, listing_id, owner_id, user_id, conversation_id, source, status, created_at) VALUES (?, ?, ?, ?, NULL, ?, ?, ?)', [
        sid(`lead:${n}:${email}`), lid, ownerId, userId(email), k % 5 === 4 ? 'wanted_offer' : 'message', status, new Date(now - (k % 12) * DAY - (k % 4) * 7_200_000).toISOString(),
      ]);
    });

    // view events for the owner stats charts (alice's and the landlord's listings), spread over the last 30 days
    const viewers = ['bob@u.northwestern.edu', 'newbie@u.northwestern.edu', 'tianyi.zhao@u.northwestern.edu', 'grace.hu@u.northwestern.edu', 'haoran.zhang@u.northwestern.edu', 'daniel.kim@u.northwestern.edu'].map(userId);
    for (const n of [1, 3, 4, 6, 9, 13]) {
      const lid = listingIds[n - 1]!;
      const total = Math.min(SPECS[n - 1]!.views, 90);
      for (let k = 0; k < total; k++) {
        const daysAgo = Math.floor((k * 7919) % 30);
        logEvent(null, 'listing.view', { entityType: 'listing', entityId: lid, userId: viewers[k % viewers.length]!, sessionId: 'seed', campusId: 'northwestern', path: `/listings/${lid}`, ts: new Date(now - daysAgo * DAY - (k % 24) * 3_600_000).toISOString() });
      }
    }
  });
  void nowIso;
}
